import images from '../content/images.generated.json';

// Responsive photo from client/public/images (generated by `npm run images`).
//
// `sizes` is how wide the frame is shown (as in <img sizes>). `box` is the
// frame's shape as width / height (1 for a circle, 0.8 for a 4:5 arch). When a
// wider photo is cropped to fill a narrower frame, the browser needs a
// proportionally wider file to stay sharp, so the sizes are scaled up to match.
export default function Photo({ name, sizes = '100vw', box, className, eager = false }) {
  const img = images[name];
  if (!img) return null;
  const srcSet = img.widths.map((w) => `/images/${name}-${w}.webp ${w}w`).join(', ');
  const fallback = img.widths[Math.min(1, img.widths.length - 1)];
  const crop = box ? img.width / img.height / box : 1;
  const scaledSizes =
    crop > 1.05
      ? sizes
          .split(',')
          .map((part) => {
            const [, media = '', length] = part.trim().match(/^(\(.*\)\s+)?(.+)$/);
            return `${media}calc(${length} * ${crop.toFixed(2)})`;
          })
          .join(', ')
      : sizes;
  return (
    <img
      src={`/images/${name}-${fallback}.webp`}
      srcSet={srcSet}
      sizes={scaledSizes}
      width={img.width}
      height={img.height}
      alt={img.alt}
      loading={eager ? 'eager' : 'lazy'}
      fetchPriority={eager ? 'high' : undefined}
      decoding="async"
      className={className}
      style={img.focus ? { objectPosition: img.focus } : undefined}
    />
  );
}
